        let conv2d56_out1 = self.conv2d56.forward(concat6_out1);
        let slice7_out1 = conv2d56_out1.clone().slice(s![.., 0..16, .., ..]);
        let batchnormalization4_out1 = self.batchnormalization4.forward(slice7_out1);
