        let relu6_out1 = burn::tensor::activation::relu(concat8_out1);
        let concat9_out1 = burn::tensor::Tensor::cat([relu5_out1, relu6_out1].into(), 1);
        let conv2d58_out1 = self.conv2d58.forward(concat9_out1);
        let slice11_out1 = conv2d58_out1.clone().slice(s![.., 0..32, .., ..]);
        let batchnormalization6_out1 = self.batchnormalization6.forward(slice11_out1);
        let slice12_out1 = conv2d58_out1.slice(s![.., 32.., .., ..]);
