        let relu17_out1 = burn::tensor::activation::relu(concat24_out1);
        let conv2d69_out1 = self.conv2d69.forward(relu17_out1);
        let sigmoid2_out1 = burn::tensor::activation::sigmoid(conv2d69_out1);
